            header_row = r
            year_to_col = {y: tmp[y] for y in expected_years}
            break
if header_row is None:
    raise SystemExit('Could not find Data header row with years')

first_year_col = min(year_to_col.values())
last_year_col = max(year_to_col.values())
first_year_letter = get_column_letter(first_year_col)
last_year_letter = get_column_letter(last_year_col)

# detect Data code column
code_candidates = {}
for col in range(1, 21):
    hits=total=0
    for r in range(21,39):
        v = norm_code(ws_data.cell(row=r, column=col).value)
        if not v:
            continue
        total += 1
        if v in expected_codes:
            hits += 1
    if total:
        code_candidates[col]=(hits,total)
if not code_candidates:
    raise SystemExit('No code column candidates')

best_col = max(code_candidates.keys(), key=lambda c: (code_candidates[c][0], code_candidates[c][1]))
code_col_letter = get_column_letter(best_col)

# stats label mapping
stats_labels = {}
for r in range(42,48):
    vals = [ws_task.cell(row=r, column=c).value for c in range(1,8)]
    label = None
    for v in vals:
        if v is None:
            continue
        s = str(v).strip()
        if s:
            label = s
            break
    if label:
        stats_labels[r] = label

label_to_row = {}
def_rows = {'MIN':42,'MAX':43,'MEDIAN':44,'AVERAGE':45,'P25':46,'P75':47}
for r,label in stats_labels.items():
    u = label.upper()
    if 'MIN' in u:
        label_to_row['MIN']=r
    elif 'MAX' in u:
        label_to_row['MAX']=r
    elif 'MEDIAN' in u:
        label_to_row['MEDIAN']=r
    elif 'SIMPLE MEAN' in u or 'AVERAGE' in u or u=='MEAN':
        label_to_row['AVERAGE']=r
    elif '25' in u and ('PERCENT' in u or 'QUART' in u or 'PCTL' in u):
        label_to_row['P25']=r
    elif '75' in u and ('PERCENT' in u or 'QUART' in u or 'PCTL' in u):
        label_to_row['P75']=r
for k,v in def_rows.items():
    label_to_row.setdefault(k,v)

# --- write formulas ---
for start,end in blocks:
    for r in range(start, end+1):
        for col_letter in TASK_YEAR_COLS:
            formula = (
                f"=INDEX(Data!${first_year_letter}$21:${last_year_letter}$38,"
                f" MATCH($D{r}, Data!${code_col_letter}$21:${code_col_letter}$38, 0),"
                f" MATCH({col_letter}$10, Data!${first_year_letter}${header_row}:${last_year_letter}${header_row}, 0))"
            )
            ws_task[f'{col_letter}{r}'].value = formula

for r in range(35,41):
    for col_letter in TASK_YEAR_COLS:
        ws_task[f'{col_letter}{r}'].value = f"=({col_letter}{r-23}-{col_letter}{r-16})/{col_letter}{r-9}*100"

for col_letter in TASK_YEAR_COLS:
    rng = f'{col_letter}35:{col_letter}40'
    ws_task[f'{col_letter}{label_to_row["MIN"]}'].value = f"=MIN({rng})"
    ws_task[f'{col_letter}{label_to_row["MAX"]}'].value = f"=MAX({rng})"
    ws_task[f'{col_letter}{label_to_row["MEDIAN"]}'].value = f"=MEDIAN({rng})"
    ws_task[f'{col_letter}{label_to_row["AVERAGE"]}'].value = f"=AVERAGE({rng})"
    ws_task[f'{col_letter}{label_to_row["P25"]}'].value = f"=PERCENTILE({rng},0.25)"
    ws_task[f'{col_letter}{label_to_row["P75"]}'].value = f"=PERCENTILE({rng},0.75)"

for col_letter in TASK_YEAR_COLS:
    ws_task[f'{col_letter}50'].value = f"=SUMPRODUCT({col_letter}35:{col_letter}40,{col_letter}26:{col_letter}31)/SUM({col_letter}26:{col_letter}31)"

# --- compute cached values ---
lookup = {}
for r in range(21,39):
    code = norm_code(ws_data[f'{code_col_letter}{r}'].value)
    if not code:
        continue
    for y in expected_years:
        col = year_to_col[y]
        v = ws_data.cell(row=r, column=col).value
        if v is None or v=='':
            continue
        if is_number(v):
            lookup[(code,y)] = float(v)
        else:
            try:
                lookup[(code,y)] = float(str(v).strip())
            except Exception:
                pass

cache_values = {}
# lookup blocks
for start,end in blocks:
    for r in range(start,end+1):
        code = norm_code(ws_task[f'D{r}'].value)
        for idx, col_letter in enumerate(TASK_YEAR_COLS):
            y = task_years[idx]
            cache_values[f'{col_letter}{r}'] = lookup.get((code,y))

# net SLA 35-40
for r in range(35,41):
    for col_letter in TASK_YEAR_COLS:
        pres = cache_values.get(f'{col_letter}{r-23}')
        cons = cache_values.get(f'{col_letter}{r-16}')
        cap = cache_values.get(f'{col_letter}{r-9}')
        if pres is None or cons is None or cap in (None,0):
            cache_values[f'{col_letter}{r}'] = None
        else:
            cache_values[f'{col_letter}{r}'] = (pres-cons)/cap*100.0

# stats
for col_letter in TASK_YEAR_COLS:
    vals = [cache_values.get(f'{col_letter}{r}') for r in range(35,41)]
    vals = [v for v in vals if v is not None]
    if not vals:
        continue
    cache_values[f'{col_letter}{label_to_row["MIN"]}'] = min(vals)
    cache_values[f'{col_letter}{label_to_row["MAX"]}'] = max(vals)
    cache_values[f'{col_letter}{label_to_row["MEDIAN"]}'] = statistics.median(vals)
    cache_values[f'{col_letter}{label_to_row["AVERAGE"]}'] = sum(vals)/len(vals)
    cache_values[f'{col_letter}{label_to_row["P25"]}'] = excel_percentile_inc(vals,0.25)
    cache_values[f'{col_letter}{label_to_row["P75"]}'] = excel_percentile_inc(vals,0.75)

# weighted mean
for col_letter in TASK_YEAR_COLS:
    weights = [cache_values.get(f'{col_letter}{r}') for r in range(26,32)]
    vals = [cache_values.get(f'{col_letter}{r}') for r in range(35,41)]
    pairs = [(v,w) for v,w in zip(vals,weights) if v is not None and w is not None]
    if not pairs:
        cache_values[f'{col_letter}50'] = None
        continue
    num = sum(v*w for v,w in pairs)
    den = sum(w for _,w in pairs)
    cache_values[f'{col_letter}50'] = (num/den) if den else None

# Save workbook with formulas
os.makedirs(os.path.dirname(OUT), exist_ok=True)
wb.save(OUT)

# --- inject cached values into Task sheet xml ---
from lxml import etree

with tempfile.TemporaryDirectory() as td:
    with zipfile.ZipFile(OUT,'r') as z:
        z.extractall(td)

    wb_xml_path = os.path.join(td,'xl','workbook.xml')
    rels_path = os.path.join(td,'xl','_rels','workbook.xml.rels')

    wb_tree = etree.parse(wb_xml_path)
    rels_tree = etree.parse(rels_path)
    ns_wb = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
    ns_rel = {'r': 'http://schemas.openxmlformats.org/package/2006/relationships'}

    sheet_el = wb_tree.xpath("//m:sheets/m:sheet[@name='Task']", namespaces=ns_wb)
    if not sheet_el:
        raise RuntimeError('Task sheet not found in workbook.xml')
    rid = sheet_el[0].get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')

    rel_el = rels_tree.xpath(f"//r:Relationship[@Id='{rid}']", namespaces=ns_rel)
    if not rel_el:
        raise RuntimeError(f'Relationship {rid} not found in workbook.xml.rels')
    target = rel_el[0].get('Target')
    if not target:
        raise RuntimeError('Task sheet target missing')

    # Target is relative to xl/ by spec, but may already be prefixed with xl/
    if target.startswith('/'):
        target = target[1:]
    if target.startswith('xl/'):
        sheet_xml_path = os.path.join(td, target)
    else:
        sheet_xml_path = os.path.join(td, 'xl', target)

    if not os.path.exists(sheet_xml_path):
        raise RuntimeError(f'Task sheet xml not found at {sheet_xml_path} (target={target})')

    sheet_tree = etree.parse(sheet_xml_path)
    ns = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

    cells = sheet_tree.xpath('//m:sheetData//m:c', namespaces=ns)
    cell_by_r = {c.get('r'): c for c in cells if c.get('r')}

    updated = 0
    for addr, val in cache_values.items():
        if val is None:
            continue
        c_el = cell_by_r.get(addr)
        if c_el is None:
            continue
        # ensure numeric
        if c_el.get('t') in ('str','inlineStr','s','b'):
            c_el.attrib.pop('t', None)
        v_el = c_el.find('m:v', namespaces=ns)
        if v_el is None:
            v_el = etree.SubElement(c_el, '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}v')
        v_el.text = fmt_number(val)
        updated += 1

    sheet_tree.write(sheet_xml_path, xml_declaration=True, encoding='UTF-8', standalone='yes')

    # rezip
    tmp_zip = OUT + '.tmp'
    with zipfile.ZipFile(tmp_zip,'w',compression=zipfile.ZIP_DEFLATED) as z:
        for root, dirs, files in os.walk(td):
            for fn in files:
                full = os.path.join(root, fn)
                rel = os.path.relpath(full, td)
                z.write(full, rel)
    os.replace(tmp_zip, OUT)

print('Injected cached values into', updated, 'cells')

# validate
wb2 = load_workbook(OUT, data_only=True)
ws2 = wb2['Task']
spots = ['H12','I12','L17','H35','L40','H42','H47','H50','L50']
print('Spot-checks (data_only=True):')
for addr in spots:
    print(addr, ws2[addr].value)

